/* ========================================
   GlobalStone — Global Styles
   ======================================== */

/* CSS Variables */
:root {
  --color-primary: #003F2D;
  --color-secondary: #012A2D;
  --color-accent: #C5A56A;
  --color-neutral: #E6E6E6;
  --color-white: #FFFFFF;
  --color-gray-100: #F5F5F5;
  --color-gray-200: #E5E5E5;
  --color-gray-300: #D4D4D4;
  --color-gray-400: #A3A3A3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;

  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background-color: var(--color-white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-gray-900);
}

h1 { font-size: clamp(2rem, 4vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: clamp(1rem, 1.5vw, 1.25rem); }

p {
  color: var(--color-gray-600);
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: var(--space-6);
  padding-right: var(--space-6);
}

@media (min-width: 768px) {
  .container {
    padding-left: var(--space-8);
    padding-right: var(--space-8);
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: var(--space-12);
    padding-right: var(--space-12);
  }
}

/* Section spacing */
.section {
  padding-top: var(--space-16);
  padding-bottom: var(--space-16);
}

.section-sm {
  padding-top: var(--space-10);
  padding-bottom: var(--space-10);
}

.section-lg {
  padding-top: var(--space-24);
  padding-bottom: var(--space-24);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.025em;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background-color: var(--color-secondary);
}

.btn-accent {
  background-color: var(--color-accent);
  color: var(--color-gray-900);
}

.btn-accent:hover {
  background-color: #b8945a;
}

.btn-outline {
  border: 1.5px solid currentColor;
  color: var(--color-primary);
}

.btn-outline:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-outline-light {
  border: 1.5px solid var(--color-white);
  color: var(--color-white);
}

.btn-outline-light:hover {
  background-color: var(--color-white);
  color: var(--color-primary);
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: 0.8125rem;
}

/* Cards */
.card {
  background: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.card-body {
  padding: var(--space-6);
}

/* Grid utilities */
.grid {
  display: grid;
  gap: var(--space-6);
}

.grid-2 {
  grid-template-columns: repeat(1, 1fr);
}

.grid-3 {
  grid-template-columns: repeat(1, 1fr);
}

.grid-4 {
  grid-template-columns: repeat(1, 1fr);
}

@media (min-width: 640px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* Flex utilities */
.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-between {
  justify-content: space-between;
}

.gap-4 {
  gap: var(--space-4);
}

.gap-6 {
  gap: var(--space-6);
}

.gap-8 {
  gap: var(--space-8);
}

/* Text utilities */
.text-center {
  text-align: center;
}

.text-white {
  color: var(--color-white);
}

.text-primary {
  color: var(--color-primary);
}

.text-accent {
  color: var(--color-accent);
}

.text-sm {
  font-size: 0.875rem;
}

.text-xs {
  font-size: 0.75rem;
}

.font-medium {
  font-weight: 500;
}

.font-semibold {
  font-weight: 600;
}

.font-bold {
  font-weight: 700;
}

.uppercase {
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Background utilities */
.bg-primary {
  background-color: var(--color-primary);
}

.bg-secondary {
  background-color: var(--color-secondary);
}

.bg-neutral {
  background-color: var(--color-neutral);
}

.bg-gray-100 {
  background-color: var(--color-gray-100);
}

.bg-white {
  background-color: var(--color-white);
}

/* Overlays */
.overlay {
  position: relative;
}

.overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.3) 60%, rgba(0,0,0,0.1) 100%);
  z-index: 1;
}

.overlay-dark::before {
  background: linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, rgba(0,0,0,0.8) 100%);
}

.overlay > * {
  position: relative;
  z-index: 2;
}

/* ========================================
   Header & Navigation
   ======================================== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base);
}

.header-scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--color-accent);
}

/* Desktop Navigation */
.nav-desktop {
  display: none;
}

@media (min-width: 1024px) {
  .nav-desktop {
    display: flex;
    align-items: center;
    gap: var(--space-8);
  }
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-gray-700);
  padding: var(--space-2) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--color-primary);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.mega-menu-wrapper {
  position: relative;
}

.mega-menu-trigger {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.mega-menu-trigger svg {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.mega-menu-wrapper.open .mega-menu-trigger svg {
  transform: rotate(180deg);
}

.mega-menu {
  position: absolute;
  top: calc(100% + 1px);
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  width: 720px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  padding: var(--space-8);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
}

.mega-menu-wrapper.open .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: var(--space-8);
}

.mega-menu-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-gray-400);
  margin-bottom: var(--space-4);
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.mega-menu-list a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-800);
  transition: color var(--transition-fast);
}

.mega-menu-list a:hover {
  color: var(--color-primary);
}

/* Mobile Navigation */
.nav-mobile {
  display: flex;
  align-items: center;
}

@media (min-width: 1024px) {
  .nav-mobile {
    display: none;
  }
}

.mobile-menu-btn {
  width: 40px;
  height: 40px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-gray-800);
  transition: all var(--transition-fast);
}

.mobile-menu-btn.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.mobile-menu-btn.active span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-btn.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-nav {
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 999;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-inner {
  padding: var(--space-6);
}

.mobile-nav-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.mobile-nav-link {
  display: block;
  padding: var(--space-4) 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
}

.mobile-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
  width: 100%;
}

.mobile-accordion-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
}

.mobile-accordion-header.active svg {
  transform: rotate(180deg);
}

.mobile-accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.mobile-accordion-body.open {
  max-height: 500px;
}

.mobile-accordion-body a {
  display: block;
  padding: var(--space-3) var(--space-4);
  font-size: 0.9375rem;
  color: var(--color-gray-600);
}

.mobile-accordion-body a:hover {
  color: var(--color-primary);
}

/* ========================================
   Hero Section
   ======================================== */
.hero {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  background-size: cover;
  background-position: center;
  padding-top: 72px;
}

.hero-content {
  max-width: 640px;
}

.hero-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent);
  margin-bottom: var(--space-4);
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  line-height: 1.6;
  color: rgba(255,255,255,0.85);
  margin-bottom: var(--space-8);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}

/* ========================================
   Announcement Banner
   ======================================== */
.announcement-banner {
  background-color: var(--color-secondary);
  padding: var(--space-4) 0;
}

.announcement-inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-3);
}

@media (min-width: 768px) {
  .announcement-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.announcement-text {
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 500;
}

/* ========================================
   Section Headers
   ======================================== */
.section-header {
  margin-bottom: var(--space-10);
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent);
  margin-bottom: var(--space-3);
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  color: var(--color-gray-900);
  margin-bottom: var(--space-4);
}

.section-desc {
  font-size: 1.0625rem;
  color: var(--color-gray-600);
  max-width: 640px;
}

/* ========================================
   Featured Insights
   ======================================== */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: var(--space-6);
}

@media (min-width: 768px) {
  .insights-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.insight-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-gray-100);
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-6);
  transition: transform var(--transition-base);
}

.insight-card:hover {
  transform: translateY(-4px);
}

.insight-card-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

.insight-card-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.2) 50%, rgba(0,0,0,0.05) 100%);
}

.insight-card-content {
  position: relative;
  z-index: 1;
}

.insight-card-tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  background: rgba(0,0,0,0.4);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-3);
}

.insight-card-title {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-white);
  line-height: 1.4;
}

/* ========================================
   About Statement
   ======================================== */
.about-statement {
  background-color: var(--color-white);
}

.about-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-text {
  font-size: clamp(1.125rem, 2.5vw, 1.5rem);
  line-height: 1.6;
  color: var(--color-gray-700);
  margin-bottom: var(--space-8);
}

/* ========================================
   What We Do Tabs
   ======================================== */
.tabs-section {
  background-color: var(--color-gray-100);
}

.tabs-wrapper {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
}

@media (min-width: 768px) {
  .tabs-wrapper {
    grid-template-columns: 280px 1fr;
  }
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.tab-btn {
  text-align: left;
  padding: var(--space-4) var(--space-5);
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-600);
  border-left: 3px solid transparent;
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  color: var(--color-gray-900);
  background: rgba(0,0,0,0.03);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-accent);
  background: var(--color-white);
  font-weight: 600;
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-panel h3 {
  font-size: 1.5rem;
  margin-bottom: var(--space-4);
}

.tab-panel p {
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

/* ========================================
   Newsletter
   ======================================== */
.newsletter-section {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.newsletter-inner {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-6);
}

@media (min-width: 768px) {
  .newsletter-inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.newsletter-content h2 {
  color: var(--color-white);
  margin-bottom: var(--space-2);
}

.newsletter-content p {
  color: rgba(255,255,255,0.8);
}

/* ========================================
   Latest Insights (list style)
   ======================================== */
.insights-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.insight-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-4);
  padding-bottom: var(--space-6);
  border-bottom: 1px solid var(--color-gray-200);
  transition: background var(--transition-fast);
}

@media (min-width: 768px) {
  .insight-row {
    grid-template-columns: 200px 1fr;
    align-items: center;
  }
}

.insight-row:hover {
  background: var(--color-gray-50);
}

.insight-row-thumb {
  width: 100%;
  height: 140px;
  background: var(--color-gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.insight-row-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.insight-row-meta {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.insight-row-tag {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-accent);
}

.insight-row-title {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-gray-900);
}

.insight-row-date {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

/* ========================================
   Commitment Pillars
   ======================================== */
.pillars-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: var(--space-6);
}

@media (min-width: 768px) {
  .pillars-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.pillar-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: var(--space-8);
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
}

